GRANT SELECT ON uiabd3_training.access_stock TO 'uiabd3_reader'@'localhost';
SHOW GRANTS FOR 'uiabd3_reader'@'localhost';

SELECT * FROM access_stock;
INSERT INTO access_stock VALUES(2,20);
UPDATE access_stock SET qty=20 WHERE id=1;
DELETE FROM access_stock WHERE id=1;

GRANT SELECT ON uiabd3_training.* TO 'uiabd3_reader'@'localhost';
REVOKE SELECT ON uiabd3_training.access_stock FROM 'uiabd3_reader'@'localhost';
SHOW GRANTS FOR 'uiabd3_reader'@'localhost';
